mapper.sql:
WHERE p.state = 'VISIBLE' AND p.screening_thread = 0
AND p.topic = #{topic}
AND p.work_id = #{workId}

c.post_id = #{postId} AND c.parent_id IS NULL AND (
  c.state = 'VISIBLE' OR EXISTS (
    SELECT 1 FROM fl_forum_comment r WHERE r.thread_root_id = c.id AND r.post_id = c.post_id AND r.state = 'VISIBLE'
  )
)
